WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units DESC NULLS LAST, id) AS row_num FROM store_sales QUALIFY row_num = 1) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, s.revenue, s.row_num, (SELECT SUM(s2.revenue) FROM store_sales s2 WHERE s2.product_id = s.product_id) AS sum_store_sale_revenue FROM latest s ORDER BY sum_store_sale_revenue;
